import { timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Shared base columns reused by every table.
 * - `id`: UUID primary key generated by the database.
 * - `createdAt` / `updatedAt`: audit timestamps with timezone.
 * - `deletedAt`: soft-delete marker (null = active row).
 */
export const basedcols = {
  id: uuid("id").primaryKey().defaultRandom(),
  createdAt: timestamp("created_at", { withTimezone: true })
    .defaultNow()
    .notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date()),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
};
